import os, json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks

def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])
    p_layers = int(instance.get("p_layers", 3))
    shots = int(instance.get("shots", 1024))

    # ── 1. Build n×n diagonal QUBO from spec formula ─────────────────
    # q_i = (cost_i / c_max - stmt_cov_i / s_max - faults_cov_i / f_max) / 3
    costs_raw = [float(item["execution_cost"]) for item in block_items]
    stmt_raw = [float(item["statement_cov"]) for item in block_items]
    faults_raw = [float(item["faults_cov"]) for item in block_items]

    c_max = max(costs_raw) if costs_raw else 1.0
    s_max = max(stmt_raw) if stmt_raw else 1.0
    f_max = max(faults_raw) if faults_raw else 1.0
    if c_max == 0:
        c_max = 1.0
    if s_max == 0:
        s_max = 1.0
    if f_max == 0:
        f_max = 1.0

    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        q_i = (costs_raw[i] / c_max - stmt_raw[i] / s_max - faults_raw[i] / f_max) / 3.0
        Q[i, i] = q_i

    # ── 2. Convert QUBO → Ising (h, J, const) ─────────────────────────
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # ── 3. Guard against all-zero block ───────────────────────────────
    if not np.any(h) and not J:
        print(json.dumps({"value": 0.0, "instance": {
            "type": "qubo", "matrix": Q.tolist(), "num_variables": n,
            "pauli_terms": []}, "bitstring": "0" * n}))
        return

    # ── 4. QAOA with p_layers — flatten gamma/beta params ─────────────
    def cost(params):
        total = 0.0
        state = None
        # Build circuit layer by layer using qaoa_blocks (reps=1 each)
        # For p>1, apply sequential cost+mixer layers manually
        from qiskit import QuantumCircuit
        qc = QuantumCircuit(n)
        for q_idx in range(n):
            qc.h(q_idx)
        for layer in range(p_layers):
            gamma = params[layer]
            beta = params[p_layers + layer]
            # cost layer: RZ on each qubit + CNOT-RZ-CNOT for J couplings
            for i_q in range(n):
                qc.rz(2.0 * gamma * h[i_q], i_q)
            for (i_q, j_q), j_val in J.items():
                qc.cx(i_q, j_q)
                qc.rz(2.0 * gamma * j_val, j_q)
                qc.cx(i_q, j_q)
            # mixer layer
            for q_idx in range(n):
                qc.rx(2.0 * beta, q_idx)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    num_params = 2 * p_layers
    x0 = np.array([0.1] * num_params)
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if res.success and res.x is not None else x0

