        for (i_q, j_q), j_val in J.items():
            qc.cx(i_q, j_q)
            qc.rz(2.0 * gamma * j_val, j_q)
            qc.cx(i_q, j_q)
        for q_idx in range(n):
            qc.rx(2.0 * beta, q_idx)
